<?php
declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';require_role('ADMIN');$error='';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$id=positive_id($_POST['transcript_id']??null,'transcript_id');$reason=text_input($_POST,'reason',1000);$s=$pdo->prepare('UPDATE transcripts SET status="REVOKED",revoked_by=?,revoked_at=NOW(),revocation_reason=? WHERE id=? AND status="VALID"');$s->execute([current_user()['id'],$reason,$id]);if(!$s->rowCount()){throw new RuntimeException('Transcript is already revoked or was not found.');}academic_audit($pdo,'TRANSCRIPT_REVOKED',(int)current_user()['id'],null,$id,null,['status'=>'REVOKED'],$reason);flash('success','Transcript revoked.');redirect('admin/transcripts.php');}catch(Throwable $e){$error=page_error($e,$errors);}}
$rows=$pdo->query('SELECT t.*,u.full_name,s.registration_number,s.programme FROM transcripts t INNER JOIN students s ON s.id=t.student_id INNER JOIN users u ON u.id=s.user_id ORDER BY t.generated_at DESC')->fetchAll();$pageTitle='Clearance Transcripts';require_once __DIR__.'/../includes/header.php';?><div class="page-heading"><div><span class="eyebrow">DOCUMENTS</span><h1>Clearance Transcripts</h1><p class="muted">Issued clearance transcripts with office approvals and verification status.</p></div></div><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><section class="panel"><div class="table-wrap"><table><thead><tr><th>Document</th><th>Student</th><th>Version</th><th>Status</th><th>Generated</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['document_number'])?></td><td><?=e($row['full_name'])?><br><small><?=e($row['registration_number'])?></small></td><td><?=e($row['version'])?></td><td><span class="<?=e($row['status']==='VALID'?'badge success':'badge danger')?>"><?=e($row['status'])?></span></td><td><?=e($row['generated_at'])?></td><td><?php if($row['status']==='VALID'):?><form method="post" onsubmit="return confirmAction('Revoke this transcript?');"><?php csrf_field();?><input type="hidden" name="transcript_id" value="<?=$row['id']?>"><input name="reason" required maxlength="1000" placeholder="Reason"><button class="btn danger small" type="submit">Revoke</button></form><?php else:?><span class="muted"><?=e($row['revocation_reason'])?></span><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">No transcripts generated yet.</td></tr><?php endif;?></tbody></table></div></section><?php require_once __DIR__.'/../includes/footer.php';?>
